NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'I Peter'

CHAPTERS = {
    1: {
        1: 'Peter, apostol Jezusa Kristusa, tujcem, razpršenim vsepovsod po Pontu, Galatiji, Kapadokiji, Aziji in Bitiniji,',
        2: 'izvoljenim glede na vnaprejšnje védenje Boga Očeta, s posvečenjem Duha, k poslušnosti in škropljenju s krvjo Jezusa Kristusa: ›Milost vam in mir naj se pomnožita.‹',
        3: 'Blagoslovljen bodi Bog in Oče našega Gospoda Jezusa Kristusa, ki nas je glede na svoje obilno usmiljenje, z vstajenjem Jezusa Kristusa od mrtvih, ponovno rodil v živo upanje,',
        4: 'k dediščini, netrohneči in neomadeževani in ki ne propada, prihranjeni v nebesih za vas,',
        5: 'ki ste varovani z Božjo močjo po veri v rešitev duš, ki je pripravljena, da se razodene v poslednjem času.',
        6: 'V kateri se silno veselite, čeprav ste sedaj za nekaj časa, če je potrebno, v potrtosti po mnogovrstnih preizkušnjah,',
        7: 'da bo preizkušenost vaše vere, ki je veliko bolj dragocena kakor zlato, ki izgineva, čeprav je to preizkušeno z ognjem, lahko najdena v hvalo, čast in slavo, ob pojavitvi Jezusa Kristusa.',
        8: '§ Katerega niste videli, vi ljubite; v katerega, čeprav ga sedaj ne vidite, vendar verujete [in] se veselite z nepopisno radostjo in polni slave,',
        9: 'ko prejemate konec svoje vere, celó rešitev svojih duš.',
        10: 'O tej rešitvi duš so poizvedovali in marljivo preiskovali preroki, ki so prerokovali o milosti, ki naj bi prišla k vam.',
        11: 'In preiskovali so kaj ali na kakšno vrsto časa je kazal Kristusov Duh, ki je bil v njih, ko je vnaprej pričeval o Kristusovem trpljenju in slavi, ki naj bi sledila.',
        12: 'Katerim je bilo razodeto, da ne njim, temveč so besede služile nam, sedaj pa so sporočene vam, po teh, ki so vam s Svetim Duhom, poslanim iz nebes, oznanili evangelij; v katere stvari želijo pogledati angeli.',
        13: 'Zatorej opašite ledja svojega uma, bodite trezni in do konca upajte na milost, ki bo privedena k vam ob razodetju Jezusa Kristusa;',
        14: 'kot poslušni otroci se ne prilagajajte glede na prejšnja poželenja, v svoji nevednosti,',
        15: 'temveč kakor je svet on, ki vas je poklical, tako bodite sveti vi, v vseh vrstah vedênja,',
        16: 'ker je pisano: »Bodite sveti, kajti jaz sem svet.«',
        17: 'In če kličete k Očetu, ki sodi brez oziranja na osebe, glede na delo vsakega človeka, preživite čas svojega začasnega bivanja tukaj v strahu,',
        18: 'ker veste, da iz vašega praznega vedênja, prejetega po izročilu od vaših očetov, niste bili odkupljeni s trohljivimi stvarmi, kot sta srebro in zlato,',
        19: 'temveč z dragoceno Kristusovo krvjo, kakor od jagnjeta brez pomanjkljivosti in brez madeža;',
        20: 'ki je bil resnično vnaprej določen, pred ustanovitvijo sveta, toda v teh poslednjih časih je bil razodet za vas,',
        21: 'ki po njem verujete v Boga, ki ga je obudil od mrtvih in mu izročil slavo; da bo vaša vera in upanje lahko v Bogu.',
        22: 'Ker ste svoje duše, v pokorščini resnici skozi Duha, očistili v nehlinjeno bratoljúbje, glejte, da goreče, s čistim srcem, ljubíte drug drugega,',
        23: 'ker ste ponovno rojeni, ne iz trohljivega semena, temveč iz netrohljivega, po Božji besedi, ki živi in ostaja na veke.',
        24: 'Kajti vse meso je kot trava in vsa človeška slava kakor cvet trave. Trava ovene in njen cvet pade proč,',
        25: 'toda Gospodova beseda vztraja za vedno. In to je beseda, ki vam je oznanjena po evangeliju.',
    },
    2: {
        1: 'Zatorej dajte na stran vso zlobnost in vso zvijačo in hinavščine in nevoščljivosti in vsa hudobna govorjenja,',
        2: '§ kot novorojeni otročiči si želite pristnega mleka besede, da boste s tem lahko rastli;',
        3: 'če je tako, ste okusili, da je Gospod milostljiv.',
        4: 'H kateremu prihajajte kakor k živemu kamnu, zares zavrnjenemu od ljudi, toda od Boga izbranemu in dragocenemu.',
        5: '§ Tudi vi ste kot živi kamni, vgrajeni [v] duhovno hišo, sveto duhovništvo, da darujete duhovne žrtve, po Jezusu Kristusu sprejemljive Bogu.',
        6: 'Zatorej je tudi vsebovano v pismu: »Glej, na Sionu položim glavni vogalni kamen, izvoljen, dragocen, in kdor veruje vanj, ne bo zbegan.«',
        7: 'Vam torej, ki verujete, je dragocen; toda tem, ki so neposlušni, je kamen, ki so ga graditelji zavrnili, ta isti postal glava vogalu',
        8: 'in kamen spotike in skala pohujšanja, celó tem, ki se spotikajo ob besedo, ki so neposlušni; za kar so bili tudi določeni.',
        9: 'Toda vi ste izbran rod, kraljevo duhovništvo, svet narod, posebni ljudje; da naj bi naznanjali hvale tistega, ki vas je iz teme poklical v svojo čudovito svetlobo;',
        10: 'ki v preteklem času niste bili ljudstvo, toda sedaj ste Božje ljudstvo; ki niste dosegli usmiljenja, toda sedaj ste usmiljenje dosegli.',
        11: 'Srčno ljubljeni, rotim vas kot tujce in romarje; vzdržite se pred mesenimi poželenji, ki se bojujejo zoper dušo;',
        12: 'imejte svoje vedênje iskreno med pogani, da bodo, medtem ko govorijo proti vam kot hudodelcem, lahko po vaših dobrih delih, ki jih bodo gledali, na dan obiskanja proslavili Boga.',
        13: '§ Zaradi Gospoda se podredite vsaki človeški odredbi; bodisi je to kralj, kot najvišji,',
        14: 'bodisi voditeljem, kot tistim, ki so po njem poslani za kaznovanje hudodelcev in za hvalo teh, ki delajo dobro.',
        15: 'Kajti taka je Božja volja, da boste s počenjanjem dobrega lahko utišali nevednost nespametnih ljudi.',
        16: 'Kot svobodni, pa svoje svobode ne uporabljajte za ogrinjalo zlonamernosti, temveč kakor Božji služabniki.',
        17: 'Spoštujte vse ljudi. Ljubite bratstvo. Bojte se Boga. Spoštujte kralja.',
        18: 'Služabniki, z vsem strahom bodite podrejeni svojim gospodarjem; ne samo dobrim in blagim, temveč tudi osornim.',
        19: 'Kajti vredno hvale je to, če človek, ki krivično trpi zaradi zavedanja pred Bogom, prenaša žalost.',
        20: 'Kajti kakšna čast je to, če boste, ko ste oklofutani zaradi svojih napak, to potrpežljivo prestali? Toda ko delate dobro in zaradi tega trpite, če to potrpežljivo prestanete, je to sprejemljivo pri Bogu.',
        21: 'Kajti celó k temu ste bili poklicani, ker je tudi Kristus trpel za nas in nam pustil zgled, da naj bi vi sledili njegovim stopinjam;',
        22: 'ki ni storil greha niti v njegovih ustih ni bilo najti zvijače;',
        23: 'ki ni ponovno zasramoval, ko je bil zasramovan; ko je trpel, ni grozil; temveč je sebe izročil njemu, ki sodi pravično;',
        24: 'ki je sam, v svojem lastnem telesu, naše grehe ponesel na les, da naj bi mi, mrtvi grehom, lahko živeli v pravičnosti; s čigar udarci z bičem ste bili ozdravljeni.',
        25: 'Kajti bili ste kakor ovce, ki so zašle, toda sedaj ste vrnjeni k Pastirju in duhovnemu Nadzorniku svojih duš.',
    },
    3: {
        1: 'Prav tako bodite, ve žene, podložne svojim lastnim soprogom; da bi bili lahko, če kateri ne ubogajo besede, prav tako pridobljeni brez besede, z vedênjem žena,',
        2: 'medtem ko gledajo vaše čisto vedênje, združeno s strahom.',
        3: 'Katerih okrasitev naj ne bo ta zunanja okrasitev, s prepletanjem las in z nošenjem zlata ali z oblačenjem oblek,',
        4: 'temveč naj bo to skriti človek srca, v tem kar ni trohljivo, celó ornament krotkega in tihega duha, kar ima v očeh Boga veliko ceno.',
        5: 'Kajti na ta način so v starih časih tudi svete ženske, ki so zaupale v Boga, sebe okrasile s tem, da so bile podložne svojim lastnim soprogom.',
        6: 'Celó kakor je Sara ubogala Abrahama in ga klicala gospodar; katere hčere ste ve, dokler delate dobro in niste prestrašene s kakršnimkoli preplahom.',
        7: 'Prav tako vi soprogi, prebivajte z njimi glede na spoznanje in dajajte čast ženi kot šibkejši posodi in kakor ste skupaj sodediči milosti življenja, da vaše molitve ne bodo ovirane.',
        8: 'Končno, bodite vsi enega mišljenja s tem, da imate sočutje drug do drugega, imejte se radi kot bratje, bodite sočutni, bodite prijazni,',
        9: 'ne vračajte zla za zlo ali posmehovanja za posmehovanje, temveč nasprotno, blagoslavljajte; ker veste, da ste bili k temu poklicani, da naj bi podedovali blagoslov.',
        10: 'Kajti kdor hoče ljubiti življenje in videti dobre dni, naj zadržuje svoj jezik od zla in svoje ustnice, da ne bodo govorile nobene zvijače.',
        11: 'Naj se ogiblje zla in dela dobro; naj išče mir in mu sledi.',
        12: 'Kajti Gospodove oči so nad pravičnimi in njegova ušesa so odprta k njihovim molitvam, toda Gospodov obraz je zoper te, ki počnejo zlo.',
        13: 'In kdo je ta, ki vam bo škodil, če boste privrženci tega, kar je dobro?',
        14: 'Toda če pa trpite zaradi pravičnosti, ste srečni; in ne bojte se njihovih strahot niti ne bodite zaskrbljeni;',
        15: '§ temveč v svojih srcih Gospoda Boga posvetite. In bodite vedno pripravljeni, s krotkostjo in strahom, dati odgovor vsakemu človeku, ki vas sprašuje za razlog upanja, ki je v vas;',
        16: 's tem, da imate dobro vest; da bodo, glede na to, da o vas govorijo hudobno, kakor o hudodelcih, lahko osramočeni tisti, ki zmotno obtožujejo vaše dobro vedênje v Kristusu.',
        17: 'Kajti bolje je, če je taka Božja volja, da trpite zaradi početja dobrega, kakor zaradi početja zlega.',
        18: 'Kajti tudi Kristus je enkrat trpel za grehe, pravični za nepravične, da bi nas lahko privedel k Bogu, je bil v mesu usmrčen, toda oživljen po Duhu,',
        19: 'po katerem je tudi šel in oznanjal duhovom v ječi;',
        20: 'ki so bili nekdaj neposlušni, ko je Božja potrpežljivost nekoč, v Noetovih dneh, čakala, medtem ko se je pripravljala barka, v kateri je bilo malo, to je osem duš, rešeno po vodi.',
        21: 'Podobna podoba kakor celó krst nas tudi sedaj rešuje (in ne odstranjuje umazanije mesa, temveč jamči o dobri vesti pred Bogom), z vstajenjem Jezusa Kristusa,',
        22: 'ki je odšel v nebesa in je na Božji desnici; podrejeni so mu bili angeli in oblasti ter moči.',
    },
    4: {
        1: 'Ker je torej Kristus za nas trpel v mesu, se podobno tudi vi oborožite z istim mišljenjem, kajti kdor je trpel v mesu, je prenehal z grehom;',
        2: 'da preostanek svojega časa v mesu ne bi več živel za človeška poželenja, temveč za Božjo voljo.',
        3: 'Kajti pretekli čas našega življenja nam lahko zadošča, da smo izvrševali voljo poganov, ko smo hodili v pohotnosti, poželenjih, vinskih izgredih, veseljačenjih, gostijah in gnusnih malikovanjih;',
        4: 'pri čemer imajo za čudno, da ne tečete z njimi k istemu izgredu upornosti, govoreč zlo o vas;',
        5: 'ki bodo dali obračun tistemu, ki je pripravljen, da sodi žive in mrtve.',
        6: '§ Zaradi tega razloga je bil evangelij oznanjen tudi tem, ki so mrtvi, da bi bili lahko sojeni po človeško, v mesu, toda glede Boga bi živeli v duhu.',
        7: 'Toda konec vseh stvari je blizu; bodite torej trezni in čujte v molitvi.',
        8: 'Bolj pa kakor karkoli drugega imejte med seboj gorečo ljubezen, kajti ljubezen pokrije množico grehov.',
        9: 'Brez godrnjanja uporabljajte gostoljubnost drug do drugega.',
        10: 'Kakor je vsak prejel dar, točno tako enako služite drug drugemu kot dobri oskrbniki mnogovrstne Božje milosti.',
        11: 'Če katerikoli človek govori, naj govori kakor Božje izreke; če katerikoli človek služi, naj to opravlja kakor iz zmožnosti, ki jo daje Bog; da bo v vseh stvareh Bog lahko proslavljen po Jezusu Kristusu, ki mu bodi hvala in gospostvo na veke vekov. Amen.',
        12: 'Ljubljeni, ne mislite čudno glede ognjene preizkušnje, ki je, da vas preizkusi, kakor da se vam je zgodila neka čudna stvar,',
        13: 'temveč se veselite, kolikor ste soudeleženci Kristusovih trpljenj; da ko se bo razodela njegova slava, boste lahko tudi veseli s silno radostjo.',
        14: '§ Če ste grajani zaradi Kristusovega imena, ste srečni; kajti na vas počiva duh slave in Boga; na njihovi strani je obrekovanje, toda na vaši strani je on proslavljen.',
        15: 'Toda nihče izmed vas naj ne trpi kot morilec ali kot tat ali kot hudodelec ali kot vtikljivec v zadeve drugih ljudi.',
        16: 'Vendar če katerikoli človek trpi kot kristjan, naj ne bo osramočen, temveč naj zaradi tega proslavlja Boga.',
        17: 'Kajti prihaja čas, da se mora sodba začeti v Božji hiši; in če se ta najprej začne pri nas, kakšen bo konec teh, ki ne ubogajo Božjega evangelija?',
        18: 'In če bo pravični komaj rešen, kje se bo pokazal brezbožnež in grešnik?',
        19: 'Zatorej naj tisti, ki trpijo glede na Božjo voljo, čuvanje svojih duš izročijo njemu kot zvestemu Stvarniku, s početjem dobrega.',
    },
    5: {
        1: 'Starešine, ki so med vami, spodbujam jaz, ki sem tudi starešina in priča Kristusovih trpljenj in tudi soudeleženec slave, ki se bo razodela;',
        2: 'pasite Božji trop, ki je med vami in prevzemite nadzor nad njim, ne s prisilo, temveč voljno; ne zaradi umazane grabežljivosti, temveč s primernim namenom;',
        3: 'niti kakor bi bili gospodarji nad Božjo dediščino, temveč zgledi tropu.',
        4: 'In ko se bo pojavil glavni Pastir, boste prejeli krono slave, ki ne propada.',
        5: 'Podobno se vi mlajši podredite starejšim. Da, vsi izmed vas bodite podrejeni drug drugemu in bodite oblečeni s ponižnostjo; kajti Bog se ponosnim upira, ponižnim pa daje milost.',
        6: 'Ponižajte se torej pod mogočno Božjo roko, da vas bo lahko ob primernem času povišal.',
        7: 'Vso svojo skrb vrzite nanj, kajti on skrbi za vas.',
        8: 'Bodite trezni, bodite oprezni, ker vaš nasprotnik hudič hodi naokrog kakor rjoveč lev in išče, koga bi lahko požrl;',
        9: 'kateremu se uprite neomajni v veri, vedoč, da so ista trpljenja dovršena v vaših bratih, ki so po svetu.',
        10: 'Toda Bog vse milosti, ki nas je poklical v svojo večno slavo po Kristusu Jezusu, potem ko ste nekaj časa trpeli, vas stori popolne, utrjene, okrepljene, vas ustali.',
        11: '§ Njemu bodi slava in gospostvo na veke vekov. Amen.',
        12: 'Po Silvánu, zvestemu bratu, sem vam, kakor mislim, napisal na kratko in spodbujal ter pričeval, da je to resnična Božja milost, v kateri stojite.',
        13: 'Pozdravlja vas cerkev, ki je v Babilonu, izvoljena skupaj z vami, in tudi Marko, moj sin.',
        14: '§ Pozdravite drug drugega s poljubom ljubezni. Mir bodi z vami vsemi, ki ste v Kristusu Jezusu. Amen.',
    },
}
